class Solution {
    vector<vector<pair<int,int>>>g;
    vector<int>val,seen;
    int limit,ans;
    void dfs(int u,int time,int score){
        if(u==0)ans=max(ans,score);
        for(auto e:g[u]){int v=e.first,w=e.second;
            if(time+w>limit)continue;
            bool fresh=seen[v]==0;++seen[v];
            dfs(v,time+w,score+(fresh?val[v]:0));--seen[v];
        }
    }
public:
    int maximalPathQuality(vector<int>& values,vector<vector<int>>& edges,int maxTime){
        int n=values.size();g.assign(n,{});val=values;seen.assign(n,0);
        for(auto &e:edges){g[e[0]].push_back({e[1],e[2]});g[e[1]].push_back({e[0],e[2]});}
        limit=maxTime;ans=0;seen[0]=1;dfs(0,0,val[0]);return ans;
    }
};
